// GENERATED by npm run sync from the website's src/cms/template.ts. Change it there.
/**
 * 模板: a block's look written in the CMS (the owner, 2026-11-16, of Bell's CMS.Net Views/Component_Styles: 「another
 * component style that also have related matched path with all templates related to this content, can express the
 * content」). Markup of the site's own components, bound to the block's fields:
 *
 *   <Card padding="lg">
 *     <Title order="2">{title}</Title>
 *     <Each in="cards"><Text c="dimmed">{#}. {body}</Text></Each>
 *     <If field="note"><Disclaimer note text="{note}" /></If>
 *     <Text size="sm">{@contact.title}</Text>
 *   </Card>
 *
 * Safe by construction: only the elements and attributes of ELEMENTS, each value checked (`attrValue`), every link one
 * of LINK's; the view (template-view.tsx) makes React elements of them, so every text is escaped, and nothing becomes
 * HTML but a rich-text field the catalog sanitised (Html). No Node and no React here: the CMS takes this file through its
 * npm run sync and checks a template with `checkTemplate` before it saves it.
 */

export type TElement = { tag: string; attrs: Record<string, string | true>; children: TNode[]; line: number };
export type TText = { text: string; line: number };
export type TNode = TElement | TText;

export const isElement = (n: TNode): n is TElement => "tag" in n;

/** A problem with a template: its code (the CMS says it in its language as template.<code>) and what it names. */
export type TProblem = { code: string; values: Record<string, string | number> };

const problem = (code: string, values: TProblem["values"] = {}): TProblem => ({ code, values });

export const LIMITS = { length: 60_000, depth: 40, elements: 3_000 } as const;

// ---- parsing ---------------------------------------------------------------------------------------------------

const ENTITIES: Record<string, string> = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " " };

const decode = (s: string) =>
  s.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (all, e: string) => {
    if (e[0] === "#") {
      const code = e[1] === "x" || e[1] === "X" ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return code > 0 && code < 0x110000 ? String.fromCodePoint(code) : all;
    }
    return ENTITIES[e.toLowerCase()] ?? all;
  });

const NAME = /[A-Za-z][A-Za-z0-9]*/y;
const ATTR = /[A-Za-z][A-Za-z0-9-]*/y;

/**
 * [src] as a tree: elements (`<Tag a="v" flag>…</Tag>`, `<Tag />`), text, comments (`<!-- -->`, dropped). Strict as XML:
 * every element closed in order, attribute values quoted. Text that is only white space goes (as in JSX); a line break in
 * text and the space around it is one space.
 */
export function parseTemplate(src: string): { nodes: TNode[]; problems: TProblem[] } {
  if (src.length > LIMITS.length)
    return { nodes: [], problems: [problem("tooLong", { max: LIMITS.length })] };
  const problems: TProblem[] = [];
  const root: TElement = { tag: "", attrs: {}, children: [], line: 1 };
  const stack: TElement[] = [root];
  let i = 0;
  let line = 1;
  let count = 0;
  const advance = (to: number) => {
    for (let k = i; k < to; k++) if (src.charCodeAt(k) === 10) line++;
    i = to;
  };
  const text = (raw: string, at: number) => {
    if (!raw.trim()) return;
    const t = raw
      .replace(/^\s*\n\s*/, "")
      .replace(/\s*\n\s*$/, "")
      .replace(/\s*\n\s*/g, " ");
    stack.at(-1)!.children.push({ text: decode(t), line: at });
  };
  while (i < src.length) {
    const lt = src.indexOf("<", i);
    const end = lt === -1 ? src.length : lt;
    if (end > i) {
      text(src.slice(i, end), line);
      advance(end);
      continue;
    }
    const at = line;
    if (src.startsWith("<!--", i)) {
      const close = src.indexOf("-->", i + 4);
      if (close === -1) {
        problems.push(problem("unclosedComment", { line: at }));
        break;
      }
      advance(close + 3);
      continue;
    }
    if (src[i + 1] === "/") {
      NAME.lastIndex = i + 2;
      const m = NAME.exec(src);
      const gt = m ? src.indexOf(">", NAME.lastIndex) : -1;
      if (!m || gt === -1 || src.slice(NAME.lastIndex, gt).trim()) {
        problems.push(problem("badTag", { line: at }));
        break;
      }
      const top = stack.at(-1)!;
      if (top === root) {
        problems.push(problem("stray", { tag: m[0], line: at }));
        break;
      }
      if (top.tag !== m[0]) {
        problems.push(problem("mismatch", { tag: m[0], open: top.tag, opened: top.line, line: at }));
        break;
      }
      stack.pop();
      advance(gt + 1);
      continue;
    }
    NAME.lastIndex = i + 1;
    const m = NAME.exec(src);
    if (!m) {
      problems.push(problem("badTag", { line: at }));
      break;
    }
    let j = NAME.lastIndex;
    const attrs: Record<string, string | true> = {};
    let selfClosed = false;
    let ok = false;
    for (;;) {
      while (j < src.length && /\s/.test(src[j]!)) j++;
      if (src.startsWith("/>", j)) {
        selfClosed = true;
        ok = true;
        j += 2;
        break;
      }
      if (src[j] === ">") {
        ok = true;
        j += 1;
        break;
      }
      ATTR.lastIndex = j;
      const a = ATTR.exec(src);
      if (!a) break;
      j = ATTR.lastIndex;
      if (a[0] in attrs) problems.push(problem("twice", { tag: m[0], attr: a[0], line: at }));
      if (src[j] === "=") {
        const q = src[j + 1];
        const close = q === '"' || q === "'" ? src.indexOf(q, j + 2) : -1;
        if (close === -1) break;
        attrs[a[0]] = decode(src.slice(j + 2, close));
        j = close + 1;
      } else attrs[a[0]] = true;
    }
    if (!ok) {
      problems.push(problem("badTag", { tag: m[0], line: at }));
      break;
    }
    if (++count > LIMITS.elements) {
      problems.push(problem("tooMany", { max: LIMITS.elements }));
      break;
    }
    const el: TElement = { tag: m[0], attrs, children: [], line: at };
    stack.at(-1)!.children.push(el);
    advance(j);
    if (selfClosed) continue;
    if (stack.length > LIMITS.depth) {
      problems.push(problem("tooDeep", { max: LIMITS.depth, line: at }));
      break;
    }
    stack.push(el);
  }
  if (!problems.length && stack.length > 1) {
    const open = stack.at(-1)!;
    problems.push(problem("unclosed", { tag: open.tag, line: open.line }));
  }
  return { nodes: root.children, problems };
}

/** A part of a text: itself, or what a binding names: a field (`name`), the number in an Each (`#`), a UI text (`@ns.key`). */
export type Part = string | { ref: string };

const REF = /^(#|@[A-Za-z][\w-]*(\.[\w-]+)+|[A-Za-z_]\w*)$/;

/** A text or an attribute's value in its parts; `{{` and `}}` are braces. Nothing when a binding is unclosed or malformed. */
export function partsOf(s: string): Part[] | undefined {
  const out: Part[] = [];
  let lit = "";
  for (let i = 0; i < s.length; i++) {
    const c = s[i]!;
    if (c === "{" && s[i + 1] === "{") {
      lit += "{";
      i++;
    } else if (c === "}" && s[i + 1] === "}") {
      lit += "}";
      i++;
    } else if (c === "{") {
      const close = s.indexOf("}", i + 1);
      const ref = close === -1 ? "" : s.slice(i + 1, close).trim();
      if (!REF.test(ref)) return undefined;
      if (lit) out.push(lit);
      lit = "";
      out.push({ ref });
      i = close;
    } else lit += c;
  }
  if (lit) out.push(lit);
  return out;
}

const hasRef = (parts: Part[]) => parts.some((p) => typeof p !== "string");

// ---- the elements ----------------------------------------------------------------------------------------------

/**
 * What an attribute takes: a token of [values], or a whole number in [int] (a decimal in [dec], a percentage with
 * [pct]), per breakpoint with [responsive] ("1 sm:2 md:3"); text; a link or an image's address (LINK); a switch; the name
 * of a field in scope, of a list field, of a rich-text field; one of the catalog's icons; a name of one's own (a zone's:
 * lower-case letters, digits, - and _).
 */
export type Spec =
  | {
      values?: readonly string[];
      int?: readonly [number, number];
      dec?: readonly [number, number];
      pct?: boolean;
      responsive?: boolean;
    }
  | "text"
  | "link"
  | "bool"
  | "field"
  | "list"
  | "html"
  | "icon"
  | "name";

const NAME_RE = /^[a-z][a-z0-9_-]{0,31}$/;

export const SIZES = ["xs", "sm", "md", "lg", "xl"] as const;
/** The site's colours a template may use (both themes): Mantine's dimmed and the site's tokens. */
export const COLORS = ["dimmed", "text", "accent", "night-text", "night-accent"] as const;
const SPACE: Spec = { values: SIZES, int: [0, 200], responsive: true };
const ALIGN: Spec = { values: ["flex-start", "center", "flex-end", "stretch", "baseline"] };
const JUSTIFY: Spec = { values: ["flex-start", "center", "flex-end", "space-between", "space-around"] };
const SIZE: Spec = { values: SIZES };
const RADIUS: Spec = { values: SIZES, int: [0, 64] };
const COLOR: Spec = { values: COLORS };

/** Style, on every element that draws a box or a text: room, width, alignment, colour, type, where it shows. */
const STYLE: Record<string, Spec> = {
  p: SPACE,
  px: SPACE,
  py: SPACE,
  pt: SPACE,
  pb: SPACE,
  m: SPACE,
  mx: SPACE,
  my: SPACE,
  mt: SPACE,
  mb: SPACE,
  maw: { int: [0, 2000], pct: true, responsive: true },
  ta: { values: ["left", "center", "right"], responsive: true },
  c: COLOR,
  fz: { values: SIZES, int: [10, 80], responsive: true },
  fw: { values: ["400", "500", "600", "700", "800"] },
  lh: { dec: [1, 2.5] },
  hiddenFrom: SIZE,
  visibleFrom: SIZE,
};

export type ElementDef = {
  attrs: Record<string, Spec>;
  /** Takes no children. */
  leaf?: boolean;
  /** Must have these attributes. */
  needs?: readonly string[];
  /** Must have exactly one of these. */
  oneOf?: readonly string[];
  /** Only within this element (control elements between are passed over). */
  inside?: string;
  /** Its children are only these (through control elements). */
  only?: readonly string[];
  /** Repeats its children (Each, Works): `{#}` is the number of each. */
  repeats?: boolean;
  /** A control element: draws nothing of its own. */
  control?: boolean;
  /** Only in a page layout (layouts.ts), never in a component's template. */
  layoutOnly?: boolean;
};

export const ELEMENTS: Record<string, ElementDef> = {
  Box: { attrs: { ...STYLE, hero: "bool" } },
  Container: { attrs: { ...STYLE, size: SIZE } },
  Stack: { attrs: { ...STYLE, gap: SPACE, align: ALIGN, justify: JUSTIFY } },
  Group: { attrs: { ...STYLE, gap: SPACE, align: ALIGN, justify: JUSTIFY, nowrap: "bool", grow: "bool" } },
  SimpleGrid: { attrs: { ...STYLE, cols: { int: [1, 6], responsive: true }, spacing: SPACE } },
  Grid: { attrs: { ...STYLE, gap: SPACE, align: ALIGN }, only: ["Col"] },
  Col: { attrs: { span: { int: [1, 12], responsive: true } }, inside: "Grid" },
  Card: { attrs: { ...STYLE, padding: SPACE, border: "bool", radius: RADIUS } },
  Center: { attrs: STYLE },
  Divider: { attrs: { ...STYLE, label: "text" }, leaf: true },
  Title: { attrs: { ...STYLE, order: { int: [1, 6] } } },
  Text: { attrs: { ...STYLE, size: SIZE } },
  Badge: {
    attrs: { ...STYLE, size: SIZE, variant: { values: ["filled", "light", "outline", "default", "dot"] } },
  },
  Anchor: { attrs: { ...STYLE, href: "link", size: SIZE }, needs: ["href"] },
  Button: {
    attrs: {
      ...STYLE,
      href: "link",
      size: SIZE,
      variant: { values: ["filled", "default", "light", "outline", "subtle"] },
    },
    needs: ["href"],
  },
  Image: {
    attrs: { ...STYLE, src: "link", alt: "text", h: { int: [16, 1600] }, radius: RADIUS },
    leaf: true,
    needs: ["src"],
  },
  Icon: { attrs: { name: "icon", size: { int: [12, 96] }, c: COLOR }, leaf: true, needs: ["name"] },
  Html: { attrs: { value: "html" }, leaf: true, needs: ["value"] },
  Accordion: {
    attrs: { ...STYLE, variant: { values: ["default", "contained", "separated", "filled"] } },
    only: ["AccordionItem"],
  },
  AccordionItem: { attrs: { title: "text" }, needs: ["title"], inside: "Accordion" },
  Disclaimer: { attrs: { note: "bool", text: "text" }, leaf: true, needs: ["text"] },
  ContactDetails: { attrs: {}, leaf: true },
  WebAppButton: {
    attrs: { size: { values: ["md"] }, variant: { values: ["filled", "default"] } },
    leaf: true,
  },
  ServiceCards: { attrs: {}, leaf: true },
  AppIcon: { attrs: { src: "link", size: { int: [16, 160] } }, leaf: true, needs: ["src"] },
  HeroArt: { attrs: { src: "link", h: { int: [80, 800] } }, leaf: true },
  Each: { attrs: { in: "list" }, needs: ["in"], repeats: true, control: true },
  If: { attrs: { field: "field", not: "field", is: "text" }, oneOf: ["field", "not"], control: true },
  Work: { attrs: { slug: "text" }, needs: ["slug"], control: true },
  Works: { attrs: {}, repeats: true, control: true },
  // Where a page's components of that zone stand, in a page layout (layouts.ts).
  Zone: { attrs: { name: "name" }, leaf: true, needs: ["name"], layoutOnly: true },
};

/** A field as a template sees it: its name, its kind (the catalog's) and, for a list, its items' fields. */
export type FieldInfo = { name: string; kind: string; fields?: FieldInfo[] };

/** What Work and Works bring into scope: a work's entry (the works global). */
export const WORK_FIELDS: FieldInfo[] = [
  { name: "slug", kind: "text" },
  { name: "name", kind: "text" },
  { name: "tagline", kind: "text" },
  { name: "lead", kind: "text" },
  { name: "status", kind: "text" },
  { name: "page", kind: "link" },
  { name: "icon", kind: "image" },
  { name: "art", kind: "image" },
];

/** The addresses a link or an image may have: the site's own, the web's, mail, a phone, an anchor. */
export const LINK = /^(\/(?!\/)|https?:\/\/|mailto:|tel:|#)/;

const BREAKPOINTS = ["base", "xs", "sm", "md", "lg", "xl"];

function token(spec: Exclude<Spec, string>, v: string): string | number | undefined {
  if (spec.values?.includes(v)) return v;
  if (spec.int && /^\d+$/.test(v)) {
    const n = Number(v);
    return n >= spec.int[0] && n <= spec.int[1] ? n : undefined;
  }
  if (spec.dec && /^\d+(\.\d+)?$/.test(v)) {
    const n = Number(v);
    return n >= spec.dec[0] && n <= spec.dec[1] ? n : undefined;
  }
  if (spec.pct && /^\d{1,3}%$/.test(v) && Number(v.slice(0, -1)) <= 100) return v;
  return undefined;
}

/**
 * An attribute's value as the view takes it, its bindings already filled in; nothing when it isn't one [spec] allows. A
 * responsive value is an object by breakpoint ({ base: 1, sm: 2 }).
 */
export function attrValue(spec: Spec, raw: string | true): unknown {
  if (spec === "bool") return raw === true || raw === "true" ? true : raw === "false" ? false : undefined;
  if (raw === true) return undefined;
  if (spec === "text") return raw;
  if (spec === "link") return LINK.test(raw) ? raw : undefined;
  if (spec === "name") return NAME_RE.test(raw) ? raw : undefined;
  if (spec === "field" || spec === "list" || spec === "html" || spec === "icon") return raw;
  const words = raw.trim().split(/\s+/);
  if (!spec.responsive || words.length === 1) return words.length === 1 ? token(spec, words[0]!) : undefined;
  const out: Record<string, string | number> = {};
  for (const [n, w] of words.entries()) {
    const [bp, v] = w.includes(":")
      ? (w.split(":", 2) as [string, string])
      : n === 0
        ? ["base", w]
        : ["", ""];
    const t = BREAKPOINTS.includes(bp) && !(bp in out) ? token(spec, v) : undefined;
    if (t === undefined) return undefined;
    out[bp] = t;
  }
  return out;
}

// ---- checking --------------------------------------------------------------------------------------------------

/** The field [name] in [scopes], the innermost first. */
export function fieldIn(scopes: FieldInfo[][], name: string): FieldInfo | undefined {
  for (let i = scopes.length - 1; i >= 0; i--) {
    const f = scopes[i]!.find((x) => x.name === name);
    if (f) return f;
  }
  return undefined;
}

/**
 * Every problem with [src] as a template for a block whose fields are [fields] (or, with [layout], as a page layout
 * whose fields are the page's): its syntax, each element and attribute against ELEMENTS, each binding against the fields
 * in scope, the UI texts ([texts], when given) and the icons ([icons], when given); a layout's zones, each once, at
 * least one. None: it can be saved.
 */
export function checkTemplate(
  src: string,
  fields: FieldInfo[],
  o: { texts?: ReadonlySet<string>; icons?: readonly string[]; layout?: boolean } = {},
): TProblem[] {
  if (!src.trim()) return [problem("empty")];
  const { nodes, problems } = parseTemplate(src);
  if (problems.length) return problems;
  const out: TProblem[] = [];
  const zones = new Set<string>();

  const refs = (parts: Part[], scopes: FieldInfo[][], counted: boolean, line: number) => {
    for (const p of parts) {
      if (typeof p === "string") continue;
      if (p.ref === "#") {
        if (!counted) out.push(problem("countOutside", { line }));
      } else if (p.ref.startsWith("@")) {
        if (o.texts && !o.texts.has(p.ref.slice(1)))
          out.push(problem("unknownText", { key: p.ref.slice(1), line }));
      } else {
        const f = fieldIn(scopes, p.ref);
        if (!f) out.push(problem("unknownField", { name: p.ref, line }));
        else if (f.kind === "list") out.push(problem("listAsText", { name: p.ref, line }));
      }
    }
  };

  const visit = (n: TNode, scopes: FieldInfo[][], parents: string[], counted: boolean) => {
    if (!isElement(n)) {
      const parts = partsOf(n.text);
      if (!parts) return void out.push(problem("badBinding", { line: n.line }));
      const up = parents.filter((p) => !ELEMENTS[p]?.control).at(-1);
      if (up && ELEMENTS[up]?.only)
        out.push(problem("only", { tag: up, allowed: ELEMENTS[up]!.only!.join(", "), line: n.line }));
      return refs(parts, scopes, counted, n.line);
    }
    const { tag, line } = n;
    const def = ELEMENTS[tag];
    if (!def) return void out.push(problem("unknownTag", { tag, line }));
    if (def.layoutOnly && !o.layout) return void out.push(problem("layoutOnly", { tag, line }));
    if (tag === "Zone" && typeof n.attrs.name === "string") {
      if (zones.has(n.attrs.name)) out.push(problem("zoneTwice", { name: n.attrs.name, line }));
      zones.add(n.attrs.name);
    }
    const real = parents.filter((p) => !ELEMENTS[p]?.control);
    if (def.inside && real.at(-1) !== def.inside)
      out.push(problem("inside", { tag, parent: def.inside, line }));
    const up = real.at(-1);
    if (up && ELEMENTS[up]?.only && !ELEMENTS[up]!.only!.includes(tag) && !def.control)
      out.push(problem("only", { tag: up, allowed: ELEMENTS[up]!.only!.join(", "), line }));
    for (const [attr, raw] of Object.entries(n.attrs)) {
      const spec = def.attrs[attr];
      if (!spec) {
        out.push(problem("unknownAttr", { tag, attr, line }));
        continue;
      }
      if (spec === "bool") {
        if (attrValue(spec, raw) === undefined)
          out.push(problem("badValue", { tag, attr, value: String(raw), line }));
        continue;
      }
      if (raw === true) {
        out.push(problem("needsValue", { tag, attr, line }));
        continue;
      }
      if (spec === "name") {
        if (attrValue(spec, raw) === undefined)
          out.push(problem("badValue", { tag, attr, value: raw, line }));
        continue;
      }
      if (spec === "field" || spec === "list" || spec === "html") {
        const f = fieldIn(scopes, raw);
        if (!f) out.push(problem("unknownField", { name: raw, line }));
        else if (spec === "list" && f.kind !== "list") out.push(problem("notList", { name: raw, line }));
        else if (spec === "html" && f.kind !== "html") out.push(problem("notHtml", { name: raw, line }));
        continue;
      }
      const parts = partsOf(raw);
      if (!parts) {
        out.push(problem("badBinding", { line }));
        continue;
      }
      refs(parts, scopes, counted, line);
      if (spec === "icon") {
        // A bound icon is the field's (an icon field); a written one must be the catalog's.
        if (!hasRef(parts) && o.icons && !o.icons.includes(raw))
          out.push(problem("noIcon", { value: raw, line }));
        continue;
      }
      // A bound value is checked when the page is drawn; a written one, now.
      if (!hasRef(parts) && attrValue(spec, raw) === undefined)
        out.push(problem("badValue", { tag, attr, value: raw, line }));
    }
    for (const a of def.needs ?? []) if (!(a in n.attrs)) out.push(problem("needs", { tag, attr: a, line }));
    if (def.oneOf && def.oneOf.filter((a) => a in n.attrs).length !== 1)
      out.push(problem("oneOf", { tag, attrs: def.oneOf.join(", "), line }));
    if (def.leaf && n.children.length) out.push(problem("leaf", { tag, line }));
    let inner = scopes;
    if (tag === "Each" && typeof n.attrs.in === "string") {
      const f = fieldIn(scopes, n.attrs.in);
      if (f?.kind === "list") inner = [...scopes, f.fields ?? []];
    }
    if (tag === "Work" || tag === "Works") inner = [...scopes, WORK_FIELDS];
    for (const c of n.children) visit(c, inner, [...parents, tag], counted || !!def.repeats);
  };

  for (const n of nodes) visit(n, [fields], [], false);
  if (o.layout && !zones.size) out.push(problem("noZone"));
  return out;
}

/**
 * A template to start from for a block of [fields]: each text field in a Text, each list in an Each with its items'
 * fields, a rich-text field in an Html, in a Stack.
 */
export function starterTemplate(fields: FieldInfo[]): string {
  const lines: string[] = ['<Stack gap="md">'];
  const one = (f: FieldInfo, indent: string) => {
    if (f.kind === "list") {
      lines.push(`${indent}<Each in="${f.name}">`);
      lines.push(`${indent}  <Card border>`);
      for (const s of f.fields ?? []) one(s, `${indent}    `);
      lines.push(`${indent}  </Card>`);
      lines.push(`${indent}</Each>`);
    } else if (f.kind === "html") lines.push(`${indent}<Html value="${f.name}" />`);
    else if (f.kind === "image")
      lines.push(`${indent}<If field="${f.name}"><Image src="{${f.name}}" /></If>`);
    else if (f.kind === "link")
      lines.push(`${indent}<If field="${f.name}"><Anchor href="{${f.name}}">{${f.name}}</Anchor></If>`);
    else if (f.kind === "work")
      lines.push(
        `${indent}<Work slug="{${f.name}}"><Text fw="600">{name}</Text><Text>{tagline}</Text></Work>`,
      );
    else if (f.kind === "icon") lines.push(`${indent}<If field="${f.name}"><Icon name="{${f.name}}" /></If>`);
    else if (f.kind === "boolean" || f.kind === "select") return;
    else lines.push(`${indent}<If field="${f.name}"><Text>{${f.name}}</Text></If>`);
  };
  for (const f of fields) one(f, "  ");
  lines.push("</Stack>");
  return lines.join("\n");
}
